-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Observes arrival without advancing the authored route unless its objective is ready.

local nav = APR.navigation
local Shared = APR.navigation._helpers
local CancelTimer = Shared.CancelTimer
local ContextCurrent = Shared.ContextCurrent
local CopyLocation = Shared.CopyLocation
local DepartureAllowed = Shared.DepartureAllowed
local Distance = Shared.Distance
local Enabled = Shared.Enabled
local HasWalkingPath = Shared.HasWalkingPath
local Now = Shared.Now
local Position = Shared.Position
local TargetMapReached = Shared.TargetMapReached
local WalkingDestinationReached = Shared.WalkingDestinationReached
local WalkingPointReached = Shared.WalkingPointReached
local WalkingPosition = Shared.WalkingPosition
local WalkingProvider = Shared.WalkingProvider

function nav:PollArrival()
    if self.worldLoading then return end
    if not Enabled() or (UnitIsDeadOrGhost and UnitIsDeadOrGhost("player")) then
        self:Cancel("inactive")
        return
    end
    if not self:IsNavigating() then return end
    if not ContextCurrent(self.context) then
        self:Cancel("step_changed")
        self:RequestUpdate()
        return
    end
    local step, position = self:GetActiveStep(), Position()
    if not position then return end
    if step.exitHousing then
        local data = APR.NavigationData
        -- The current map can temporarily become a continent while still in
        -- the housing world. Require a real outside-world observation.
        if
            data.IsHousingLocation
            and data:IsHousingLocation(position) == false
            and position.instanceID ~= step.from.instanceID
        then
            self:Cancel("housing_exit_complete")
            self:ForceRefresh("housing_exit_complete")
            self:RequestUpdate()
        end
        return
    end
    if step.kind == "unlock" then
        if APR.RefreshNavigationUnlockRoute then APR:RefreshNavigationUnlockRoute() end
        if self.dirty then self:RequestUpdate() end
        return
    end
    if step.kind == "verify_taxi" then return end
    local onTaxi = UnitOnTaxi and UnitOnTaxi("player")
    if step.kind == "taxi" and onTaxi then
        -- Manual boarding may happen before the next off-taxi origin poll.
        -- Native taxi travel is itself proof that this leg has departed.
        step.boarded, step.departureSeen = true, true
        return
    end
    if step.kind ~= "walk" and (step.sourceFree or Distance(position, step.from) <= 30) then
        step.departureSeen = true
    end
    local inputs = self._routeInputs
    if
        step.kind == "walk" and step ~= self.walkingPrefix and not self.travelPrefix and self.cursor == #self.queue
        and inputs and inputs.geometryRevision == APR.navigationGeometryRevision
        and self:IsLocalObjectiveInRange(inputs.step, position, self.destination, IsIndoors and IsIndoors() == false)
        and self:IsObjectiveCurrent(inputs)
        and APR.NavigationData:CanWalk(position, self.destination) == true
    then
        inputs.stoppedInRange = true
        self:MarkRouteReady(true)
        return
    end
    local flight = HasWalkingPath(step) and step.path.flight
    local walkingProvider = HasWalkingPath(step) and not flight and WalkingProvider() or nil
    if walkingProvider then
        self.lastWalkCorridor, self.lastWalkGeometry = step, APR.navigationGeometryRevision
    else
        self.lastWalkCorridor = nil
    end
    if walkingProvider then
        -- Comparing candidates may evict pages for a later corridor. Restore
        -- its next chords in bounded slices before using them for live floors.
        if
            (step.walkingLanding or self.waypointApproach or self.destination and self.destination.indoors ~= nil)
            and walkingProvider.CreateWalkingSegmentJob
            and walkingProvider.CanFollowWalkingSegment
        then
            local cursor = step.pathCursor or 2
            for index = cursor, math.min(cursor + 1, #step.path) do
                local from, to = step.path[index - 1], step.path[index]
                local pending = step.pathTerrainIndex == index and step.pathTerrainJob
                if pending or walkingProvider:CanFollowWalkingSegment(from, to) == nil then
                    local job = pending or walkingProvider:CreateWalkingSegmentJob(from, to, {})
                    if job and job:Step(256, 1) == "planning" then
                        step.pathTerrainJob, step.pathTerrainIndex = job, index
                        return
                    end
                    step.pathTerrainJob, step.pathTerrainIndex = nil, nil
                    break
                end
            end
        end
        position = self:ObserveWalkingPosition(position, walkingProvider)
        position = WalkingPosition(position, walkingProvider, step)
    end
    local pathReached = self:AdvanceWalkingPath(step, position, walkingProvider)
        or (not flight and WalkingDestinationReached(step, position, walkingProvider))
    if flight and self:IsAirborne() then return end
    local arrived = pathReached
        and Distance(position, step.to)
            <= (step.arrivalRange or step.arrivalRadius or (step.kind == "taxi" and 100 or 20))
    local goalRange = self._routeInputs and self._routeInputs.walkingGoalRange
    if
        pathReached
        and HasWalkingPath(step)
        and step ~= self.walkingPrefix
        and not self.travelPrefix
        and self.cursor == #self.queue
        and goalRange
    then
        arrived = Distance(position, step.to) < goalRange
            and (flight or WalkingPointReached(position, step.path[#step.path], walkingProvider))
    end
    local coarseMap
    if arrived then
        arrived, coarseMap = TargetMapReached(position, step.to)
        if not arrived and walkingProvider and step.kind == "walk" then
            arrived = WalkingPointReached(position, step.path[#step.path], walkingProvider)
        end
    end
    local endpoint = HasWalkingPath(step) and not flight and step.path[#step.path]
    local sharedFloorArrival = endpoint and endpoint.sharedFloorChord
    local arrivalZ, arrivalZTolerance = step.to.z, step.arrivalZTolerance
    if endpoint then
        arrivalZ = arrivalZ or endpoint.z
        arrivalZTolerance = arrivalZTolerance or 5
    end
    if arrived and flight and arrivalZ ~= nil and position.z == nil then
        position = WalkingPosition(position, WalkingProvider(), step)
    end
    local data = APR.NavigationData
    if arrived and not sharedFloorArrival and arrivalZTolerance and arrivalZ ~= nil then
        if position.z ~= nil then
            arrived = math.abs(position.z - arrivalZ) <= arrivalZTolerance
        else
            -- A lift with separately observed access regions can use the
            -- destination region to prove arrival on clients without Z.
            arrived = step.kind == "elevator"
                and step.arrivalRadius
                and data
                and data.IsSameAccessRegion
                and data:IsSameAccessRegion(position, step.to)
                and not data:IsSameAccessRegion(position, step.from)
        end
    end
    if arrived and step.arrivalRange and data then
        arrived = data:IsServiceArrival(position, sharedFloorArrival and endpoint or step.to, step.arrivalRange)
    end
    if arrived and data and data.IsSameAccessRegion then
        -- Explicit passage endpoints may forbid automatic graph connections.
        -- Arrival still succeeds there, but never from a different floor/region.
        arrived = data:IsSameAccessRegion(position, step.to)
    end
    if step.kind == "taxi" then arrived = arrived and step.boarded == true end
    if step.kind ~= "walk" then arrived = arrived and step.departureSeen and not onTaxi end
    if arrived then
        if flight and self._routeInputs then self._routeInputs.flightAirborne = false end
        if step.kind ~= "walk" then self.walkingObservation = nil end
        if step == self.walkingPrefix then
            self.queue, self.cursor, self.state = {}, 1, "planning"
            self:Notify()
            return
        end
        local leg = self.waypointPendingLeg
        local completingFixedLeg = leg and self.search and leg.before == self.queue
        if step == self.travelPrefix and not completingFixedLeg then
            local landing = step.to
            self:Cancel("transport_arrived")
            if landing.z ~= nil then self.transportLanding = landing end
            self:ForceRefresh("transport_arrived")
            self:RequestUpdate()
            return
        end
        if step.approachOnly then
            local approach = self.waypointApproach
            if approach then
                approach.reached, approach.observation = true, CopyLocation(position)
            end
            self.queue, self.cursor, self.recomputeKeepingPath = {}, 1, nil
            self.state, self.reason = self.search and "planning" or "no_path", "waypoint_approach"
            self:Notify()
            return
        end
        -- A background result was measured from the preceding leg. Do not let
        -- its eventual callback rewind an itinerary that has already advanced.
        if self.search and not completingFixedLeg then
            self.generation = self.generation + 1
            self:CancelLocalPath()
            self.search:Cancel()
            self.search = nil
            CancelTimer(self._searchTimer)
            self._searchTimer = nil
            self.recomputeKeepingPath = nil
        end
        self.cursor = self.cursor + 1
        local nextStep = self:GetActiveStep()
        if not nextStep then
            if completingFixedLeg then
                if step.kind ~= "walk" and step.to.z ~= nil then self.transportLanding = step.to end
                self.state = "planning"
                self:Notify()
            else
                self:MarkRouteReady(nil, position, sharedFloorArrival and endpoint or nil)
            end
        else
            if self.waypointJourney and nextStep.kind ~= "walk" and Distance(position, nextStep.from) <= 30 then
                nextStep.departureSeen = true
            end
            if
                (
                    (step.kind == "elevator" or step.kind == "passage")
                        and step.arrivalRadius
                        and data
                        and data.IsSameAccessRegion
                        and data:IsSameAccessRegion(position, step.from) == false
                    or self.waypointJourney and step.from.instanceID ~= step.to.instanceID
                )
                and step.to.z ~= nil
                and HasWalkingPath(nextStep)
                and Distance(step.to, nextStep.path[1]) <= 0.01
                and nextStep.path[1].z ~= nil
                and math.abs(step.to.z - nextStep.path[1].z) <= 5
            then
                nextStep.walkingLanding = true
            end
            self:Notify()
        end
        if step.kind ~= "walk" then
            -- Keep this short-lived receipt after advancing too: the arrival
            -- poll and the delayed world-event callback can run in either order.
            self._transitionArrival = {
                queue = self.queue,
                cursor = self.cursor,
                inputs = self._routeInputs,
                target = step.to,
                position = position,
                time = Now(),
                zTolerance = position.z ~= nil and step.arrivalZTolerance or nil,
                mapPending = coarseMap == true,
            }
            self._resumeAfterTransition = true
            self._transitionProbe = nil
        end
    elseif DepartureAllowed(step, position) ~= true then
        -- Arrival wins over departure restrictions after an actual transport.
        -- Otherwise remove stale actions immediately and refresh the route.
        self:ForceRefresh()
        self:Render()
        self:RequestUpdate()
    end
end--[[APR_DIAG]]; nav.PollArrival = APRTrace("APR-Core/features/navigation/controller/NavigationArrival.lua:25:nav:PollArrival#1", nav.PollArrival)--[[/APR_DIAG]]
